  values (v_release_id, (select id from public.learning_units where release_id = v_release_id and source_key = '01_Domain_1_Hub_Communication_and_Rapport'), (select id from public.learning_unit_kinds where key = 'station'), '03_Station_1.2_Nothing_Is_Wrong', 'station-1.2-nothing-is-wrong', '1.2', 3, 3, 'The Patient Who Says Nothing Is Wrong', true, jsonb_build_object('source_filename', '03_Station_1.2_Nothing_Is_Wrong.html'))
