  values (v_release_id, (select id from public.learning_units where release_id = v_release_id and source_key = '06_Domain_2_Hub_Information_Giving'), (select id from public.learning_unit_kinds where key = 'station'), '10_Station_2.4_ECT_Explained', 'station-2.4-ect-explained', '2.4', 10, 10, 'ECT, Explained', true, jsonb_build_object('source_filename', '10_Station_2.4_ECT_Explained.html'))
