  values (v_release_id, (select id from public.learning_units where release_id = v_release_id and source_key = '13_Domain_3_Hub_Risk_Assessment'), (select id from public.learning_unit_kinds where key = 'station'), '15_Station_3.2_The_Violent_Inpatient', 'station-3.2-the-violent-inpatient', '3.2', 15, 15, 'The Violent Inpatient', true, jsonb_build_object('source_filename', '15_Station_3.2_The_Violent_Inpatient.html'))
