  values (v_release_id, (select id from public.learning_units where release_id = v_release_id and source_key = '21_Domain_4_Hub_Mental_State_Examination'), (select id from public.learning_unit_kinds where key = 'station'), '22_Station_4.1_Hearing_Voices', 'station-4.1-hearing-voices', '4.1', 22, 22, 'Hearing Voices', true, jsonb_build_object('source_filename', '22_Station_4.1_Hearing_Voices.html'))
