  values (v_release_id, null, (select id from public.learning_unit_kinds where key = 'module_hub'), '38_Domain_6_Hub_Management_and_Emergencies', 'domain-6-hub-management-and-emergencies', null, 38, 38, 'Management & the Psychiatric Emergency', true, jsonb_build_object('source_filename', '38_Domain_6_Hub_Management_and_Emergencies.html'))
