  values (v_release_id, (select id from public.learning_units where release_id = v_release_id and source_key = '38_Domain_6_Hub_Management_and_Emergencies'), (select id from public.learning_unit_kinds where key = 'station'), '41_Station_6.3_Postpartum_Psychosis', 'station-6.3-postpartum-psychosis', '6.3', 41, 41, 'Postpartum Psychosis', true, jsonb_build_object('source_filename', '41_Station_6.3_Postpartum_Psychosis.html'))
