  values (v_release_id, null, (select id from public.learning_unit_kinds where key = 'module_hub'), '43_Domain_7_Hub_Difficult_Conversations', 'domain-7-hub-difficult-conversations', null, 43, 43, 'Difficult Conversations, Families & the MDT', true, jsonb_build_object('source_filename', '43_Domain_7_Hub_Difficult_Conversations.html'))
