  values (v_release_id, (select id from public.learning_units where release_id = v_release_id and source_key = '43_Domain_7_Hub_Difficult_Conversations'), (select id from public.learning_unit_kinds where key = 'station'), '44_Station_7.1_The_Patient_Who_Wont_Take_No', 'station-7.1-the-patient-who-wont-take-no', '7.1', 44, 44, 'The Patient Who Won’t Take No', true, jsonb_build_object('source_filename', '44_Station_7.1_The_Patient_Who_Wont_Take_No.html'))
