  values (v_release_id, (select id from public.learning_units where release_id = v_release_id and source_key = '48_Domain_8_Hub_Physical_Examination'), (select id from public.learning_unit_kinds where key = 'station'), '51_Station_8.3_Cranial_Nerve_Examination', 'station-8.3-cranial-nerve-examination', '8.3', 51, 51, 'Cranial Nerve Examination', true, jsonb_build_object('source_filename', '51_Station_8.3_Cranial_Nerve_Examination.html'))
